import numpy as np

# MECHANISM: Use a modified piecewise linear function with a focus on encouraging the use of smaller bins.

def priority(item, bins):
    max_capacity = 150
    # Define breakpoints for the piecewise linear function
    breakpoints = [0, 30, 60, 90, 120, 150]
    # Initialize scores array with the same shape as bins
    scores = np.zeros_like(bins)

    for i in range(len(bins)):
        remaining_capacity = bins[i]
        if remaining_capacity >= max_capacity:
            scores[i] = 0
        else:
            for j in range(len(breakpoints) - 1):
                if remaining_capacity < breakpoints[j + 1]:
                    # Calculate the score using a piecewise linear function
                    scores[i] = (breakpoints[j + 1] - remaining_capacity) / (breakpoints[j + 1] - breakpoints[j])
                    break

    return scores

