    return bins * decay_factor * np.log(bins + 1)

import numpy as np

# MECHANISM: Use a modified exponential decay function for preference scores based on remaining capacity.

def priority(item, bins):
    max_capacity = 150
    def s(b, item):
        g = b - item
        if g <= 0: return 0
        return 1 - np.exp(-(g - 1) / 20)
    return np.array([s(b, item) for b in bins]) * (max_capacity - bins) / max_capacity
